module vault_security (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] A,\n    input wire [3:0] B,\n    input wire [3:0] L,\n    output reg [15:0] insecure,\n    output reg [15:0] secure,\n    output reg [15:0] super_secure,\n    output reg done\n);\n\n    // State definitions - explicit widths\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] INIT    = 3'd1;\n    localparam [2:0] COMPUTE = 3'd2;\n    localparam [2:0] INCR_J  = 3'd3;\n    localparam [2:0] INCR_X  = 3'd4;\n    localparam [2:0] DONE_ST = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [3:0] x_reg;\n    reg [4:0] j_reg;\n    wire [4:0] max_j = A + B;\n\n    // Counters\n    reg [15:0] cnt_ins, cnt_sec, cnt_sup;\n\n    // Coprimality check function (max 16)\n    function automatic is_coprime(input [3:0] a, b);\n        begin\n            if (a == 4'd0 || b == 4'd0) \n                is_coprime = 1'b0;\n            else begin\n                if (a%4'd2==0 && b%4'd2==0) is_coprime = 1'b0;\n                else if (a%4'd3==0 && b%4'd3==0) is_coprime = 1'b0;\n                else if (a%4'd5==0 && b%4'd5==0) is_coprime = 1'b0;\n                else if (a%4'd7==0 && b%4'd7==0) is_coprime = 1'b0;\n                else if (a%4'd11==0 && b%4'd11==0) is_coprime = 1'b0;\n                else if (a%4'd13==0 && b%4'd13==0) is_coprime = 1'b0;\n                else is_coprime = 1'b1;\n            end\n        end\n    endfunction\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            x_reg <= 4'd0;\n            j_reg <= 5'd0;\n            cnt_ins <= 16'd0;\n            cnt_sec <= 16'd0;\n            cnt_sup <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            x_reg <= (next_state == INIT) ? 4'd1 : x_reg;  // Reset x on INIT\n\n            case (next_state)\n                COMPUTE: begin\n                    j_reg <= j_reg;\n                    // Automatically update counters based on coprimality\n                    cnt_ins <= insecure;\n                    cnt_sec <= secure;\n                    cnt_sup <= super_secure;\n                end\n                INCR_J: begin\n                    j_reg <= (j_reg < max_j) ? j_reg + 5'd1 : 5'd0;\n                end\n                INCR_X: begin\n                    if (x_reg < L) x_reg <= x_reg + 4'd1;\n                end\n                default: ; // Default retains values\n            endcase\n        end\n    end\n\n    // Combinational next-state logic\n    always @(*) begin\n        next_state = state;\n        insecure = cnt_ins;\n        secure = cnt_sec;\n        super_secure = cnt_sup;\n        done = 1'b0;\n\n        case (state)\n            IDLE: next_state = start ? INIT : IDLE;\n\n            INIT: next_state = COMPUTE;\n\n            COMPUTE: begin\n                // Calculate coprimality\n                reg both_coprime = is_coprime(x_reg, j_reg) && is_coprime(x_reg, max_j - j_reg);\n                reg one_coprime  = is_coprime(x_reg, j_reg) ^ is_coprime(x_reg, max_j - j_reg);\n\n                // Update outputs immediately\n                insecure = both_coprime ? cnt_ins : (one_coprime ? cnt_ins : cnt_ins + 16'd1);\n                secure   = both_coprime ? cnt_sec : (one_coprime ? cnt_sec + 16'd1 : cnt_sec);\n                super_secure = both_coprime ? cnt_sup + 16'd1 : cnt_sup;\n\n                next_state = INCR_J;\n            end\n\n            INCR_J: next_state = (j_reg < max_j) ? COMPUTE : INCR_X;\n\n            INCR_X: begin\n                if (x_reg < L) next_state = COMPUTE;\n                else next_state = DONE_ST;\n            end\n\n            DONE_ST: begin\n                done = 1'b1;\n                next_state = start ? DONE_ST : IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\nendmodule